import os, re

d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read()

def load_all():
    G = {}
    pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n'

    for m in re.finditer(pattern, t):
        k, h_str, w_str = m[1], m[2], m[3]
        h, w = int(h_str), int(w_str)

        # Extract grid rows starting after this match
        remainder = t[m.end():].split('\n')[:h]
        valid_rows = []
        for r in remainder:
            if r.strip():
                try:
                    row = [int(x) for x in r.split()]
                    valid_rows.append(row)
                except:
                    pass

        if valid_rows and len(valid_rows[0]) == w:
            grid = valid_rows
            if k not in G:
                G[k] = {'shape': (h, w), 'grid': grid}

    return G

G = load_all()
print("Keys:", sorted(G.keys()))
for k, v in G.items():
    print(f"{k}: shape={v['shape']}")

